// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.splice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  //normaliza minimo para numero
  obj.minimo = Number(String(obj.minmo).replace(/{^\d}/g, "")) // 0:

  return obj;
});

return { json: { investimentos } };

// Captura os dados do primeiro item de entrada usando a variável global 'items'
const inputData = items[0].json;

const clientes = inputData.body?.clientes || [];
const investimentos = inputData.investimentos || [];

// Mapeia cada cliente criando a mensagem personalizada baseada no perfil
const resultado = clientes.map(cliente => {
  // Filtra os investimentos que combinam com o perfil do cliente
  const opcoesInvestimento = investimentos.filter(inv => inv.perfil === cliente.perfil);

  // Monta o texto com as opções de produtos
  const listaProdutos = opcoesInvestimento.map(inv => {
    return `- ${inv.produto} (Rentabilidade: ${inv.rentabilidade})`;
  }).join('\n');

  // Cria a mensagem personalizada
  const mensagem = `Olá, ${cliente.nome}!\n\n` +
    `Identificamos que você possui um saldo disponível de ${cliente.saldo}. ` +
    `Como o seu perfil de investidor é *${cliente.perfil}*, separamos algumas oportunidades recomendadas para você:\n\n` +
    `${listaProdutos}\n\n` +
    `Fale com o seu consultor para começar a render!`;

  // Retorna a estrutura padrão que o n8n espera (um objeto json por item)
  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      mensagemPersonalizada: mensagem
    }
  };
});

return resultado;

// Captura todos os itens individuais vindos do nó anterior de forma oficial no n8n v1+
const itensEntrada = $input.all();

const tabelaNormalizada = [];

// Varre cada item recebido para extrair as variáveis
itensEntrada.forEach(item => {
  const dados = item.json;

  tabelaNormalizada.push({
    json: {
      nome: dados.nome,
      email: dados.email,
      saldo: dados.saldo,
      perfil: dados.perfil,
      mensagemPersonalizada: dados.mensagemPersonalizada
    }
  });
});

return tabelaNormalizada;

