// Captura todos os itens individuais do nó anterior de forma segura no n8n v1+
const itensEntrada = $input.all();

const emailsFormatados = [];

itensEntrada.forEach(item => {
  try {
    // 1. Acessa o texto bruto que contém o bloco JSON
    let textoBruto = item.json.content?.[0]?.text || "";

    if (textoBruto) {
      // 2. Limpa as marcações de bloco de código do markdown (```json e ```)
      textoBruto = textoBruto.replace(/```json\n/g, "").replace(/```/g, "").trim();

      // 3. Converte a string limpa em um objeto JSON real do JavaScript
      const dadosEmail = JSON.parse(textoBruto);

      // 4. Adiciona o item formatado na lista de saída do n8n
      emailsFormatados.push({
        json: {
          assunto: dadosEmail.subject,
          to: dadosEmail.to,
          corpo_texto: dadosEmail.text_body,
          corpo_html: dadosEmail.html_body
        }
      });
    }
  } catch (erro) {
    // Caso algum item venha quebrado ou incompleto (ex: o do Daniel que foi cortado), 
    // ele não derruba o fluxo e registra o erro
    emailsFormatados.push({
      json: {
        erro: "Não foi possível processar este item",
        detalhe: erro.message,
        dados_originais: item.json
      }
    });
  }
});

return emailsFormatados;
